//! A bounded work queue with cancellation support.
//!
//! The queue has a fixed capacity. Producers block when the queue is full,
//! consumers block when the queue is empty. Cancellation is cooperative:
//! a `CancellationToken` can be used to wake blocked producers/consumers
//! and to make subsequent operations fail fast.

use std::collections::VecDeque;
use std::fmt;
use std::sync::{Arc, Condvar, Mutex};

/// Token used to signal cancellation to a [`BoundedQueue`].
///
/// Cheap to clone; all clones share the same state.
#[derive(Clone, Default)]
pub struct CancellationToken {
    inner: Arc<CancelInner>,
}

#[derive(Default)]
struct CancelInner {
    cancelled: Mutex<bool>,
    condvar: Condvar,
}

impl CancellationToken {
    /// Creates a new token in the non-cancelled state.
    pub fn new() -> Self {
        Self::default()
    }

    /// Returns `true` if cancellation has been signalled.
    pub fn is_cancelled(&self) -> bool {
        *self.inner.cancelled.lock().unwrap()
    }

    /// Signals cancellation and wakes all waiters.
    pub fn cancel(&self) {
        let mut cancelled = self.inner.cancelled.lock().unwrap();
        *cancelled = true;
        self.inner.condvar.notify_all();
    }

    /// Blocks until cancellation is signalled.
    pub fn wait(&self) {
        let mut cancelled = self.inner.cancelled.lock().unwrap();
        while !*cancelled {
            cancelled = self.inner.cancelled.lock().unwrap();
        }
    }
}

impl fmt::Debug for CancellationToken {
    fn main() {}
}

impl fmt::Debug for CancellationToken {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("CancellationToken")
            .field("cancelled", &self.is_cancelled())
            .sync()
    }
}

